<?php
namespace App\Http\Controllers\Admin;
use App\Enums\TicketPriority; use App\Http\Controllers\Controller; use App\Models\{BusinessCalendar,Category,SlaPolicy}; use Illuminate\Http\Request;
class SlaPolicyController extends Controller {
public function calendars(){return view('admin.sla.calendars',['calendars'=>BusinessCalendar::with('hours','holidays')->orderByDesc('is_default')->get()]);}
public function storeHoliday(Request $r,BusinessCalendar $calendar){$d=$r->validate(['holiday_date'=>'required|date','name'=>'required|string|max:160','is_working_day'=>'nullable|boolean','opens_at'=>'nullable|required_if:is_working_day,1|date_format:H:i','closes_at'=>'nullable|required_if:is_working_day,1|date_format:H:i']);if(($d['is_working_day']??false) && $d['closes_at']<=$d['opens_at'])return back()->withErrors(['closes_at'=>'O fechamento deve ocorrer após a abertura.']);$calendar->holidays()->updateOrCreate(['holiday_date'=>$d['holiday_date']],$d+['is_working_day'=>$r->boolean('is_working_day')]);return back()->with('status','Exceção de calendário salva.');}
public function deleteHoliday(BusinessCalendar $calendar,\App\Models\BusinessHoliday $holiday){abort_unless((int)$holiday->business_calendar_id===(int)$calendar->id,404);$holiday->delete();return back()->with('status','Exceção removida.');}
public function saveCalendar(Request $r){$d=$r->validate(['calendar_id'=>'nullable|exists:business_calendars,id','name'=>'required|string|max:120','timezone'=>'required|timezone','hours'=>'array','hours.*.*.opens_at'=>'nullable|date_format:H:i','hours.*.*.closes_at'=>'nullable|date_format:H:i']);foreach($d['hours']??[] as $weekday=>$segments)foreach($segments as $segment=>$range)if(!empty($range['opens_at'])&&!empty($range['closes_at'])&&$range['closes_at']<=$range['opens_at'])return back()->withErrors(["hours.$weekday.$segment.closes_at"=>'O fechamento deve ocorrer após a abertura.'])->withInput();\Illuminate\Support\Facades\DB::transaction(function()use($d,&$calendar){$calendar=BusinessCalendar::updateOrCreate(['id'=>$d['calendar_id']??null],['name'=>$d['name'],'timezone'=>$d['timezone'],'is_active'=>true]);if($calendar->wasRecentlyCreated)$calendar->is_default=BusinessCalendar::count()===1;$calendar->save();$calendar->hours()->delete();foreach($d['hours']??[] as $weekday=>$segments)foreach($segments as $segment=>$range)if(!empty($range['opens_at'])&&!empty($range['closes_at']))$calendar->hours()->create(['weekday'=>$weekday,'segment'=>$segment,'opens_at'=>$range['opens_at'],'closes_at'=>$range['closes_at']]);});return back()->with('status','Calendário e horários atualizados.');}
public function index(){return view('admin.sla.index',['policies'=>SlaPolicy::with(['calendar','category'])->orderBy('priority')->paginate(20)]);}
public function create(){return view('admin.sla.form',['slaPolicy'=>new SlaPolicy,'priorities'=>TicketPriority::cases(),'calendars'=>BusinessCalendar::where('is_active',true)->get(),'categories'=>Category::where('is_active',true)->get()]);}
public function store(Request $r){$d=$this->validateData($r);$d['created_by']=$r->user()->id;SlaPolicy::create($d);return redirect()->route('admin.sla.index')->with('status','Política SLA criada.');}
public function edit(SlaPolicy $slaPolicy){return view('admin.sla.form',['slaPolicy'=>$slaPolicy,'priorities'=>TicketPriority::cases(),'calendars'=>BusinessCalendar::where('is_active',true)->get(),'categories'=>Category::where('is_active',true)->get()]);}
public function update(Request $r,SlaPolicy $slaPolicy){$slaPolicy->update($this->validateData($r));return redirect()->route('admin.sla.index')->with('status','Política SLA atualizada.');}
public function destroy(SlaPolicy $slaPolicy){abort_if($slaPolicy->tickets()->exists(),409,'Política vinculada a solicitações; desative-a em vez de excluir.');$slaPolicy->delete();return back()->with('status','Política removida.');}
private function validateData(Request $r):array{return $r->validate(['name'=>'required|string|max:120','priority'=>'required|in:low,medium,high,critical','category_id'=>'nullable|exists:categories,id','business_calendar_id'=>'required|exists:business_calendars,id','target_minutes'=>'required|integer|min:1|max:100000','warn_before_minutes'=>'required|integer|min:0|max:100000','effective_from'=>'required|date','effective_until'=>'nullable|date|after_or_equal:effective_from','is_active'=>'nullable|boolean']);}}
